import Foundation

enum EventEffect: Sendable {
    case hype(Double)
    case hardware(Double)
    case consumerGPU(Double)
    case rent(Double)
    case leadTime(Double)
    case apiPrice(Double)
    case exportControls
    case euAIAct
    case copyrightHeat(Double)
    case buildDelay(Double)
    case chatMoment
}

struct HistoricalEvent: Identifiable, Sendable {
    let id: String
    let date: Date
    let title: String
    let body: String
    let category: NewsCategory
    let image: String?
    let effects: [EventEffect]
    /// The rival lab (competitor ID) the event is about. It doesn't happen — effects included — if that lab
    /// has been acquired, gone bankrupt or otherwise left the market by then.
    var lab: String? = nil
}

