    static func hypeBase(_ y: Double) -> Double {
        interpolate([(2016, 1.0), (2020.5, 1.05), (2022.85, 1.0), (2023.2, 1.3), (2024.5, 1.38), (2025.5, 1.42), (2026.5, 1.45), (2028, 1.3), (2031, 1.2)], at: y)
